package com.menta.auth.application.port.out;

/**
 * Cross-module port to hash opaque activation tokens before persistence
 * (auth-account-activation spec: "Secreto de activación" — only the
 * SHA-256 digest may reach MySQL, never the raw value).
 */
public interface ActivationTokenHasher {

    /**
     * @param rawToken URL-safe raw activation token as generated by
     *                 {@link ActivationTokenGenerator}.
     * @return 64-char lowercase hex digest suitable for column token_hash.
     */
    String hash(String rawToken);
}
